      "“ἐλθὲ δεῦρο, ὦ Ξανθία. τί καθεύδεις; μὴ οὕτως ἀργὸς ἴσθι ἀλλὰ σπεῦδε.”",
      "ὁ οὖν Ξανθίας βραδέως ἐκβαίνει ἐκ τοῦ οἴκου καὶ λέγει·",
