      "ὁ δὲ Δικαιόπολις λέγει·",
      "“ἐλθὲ δεῦρο καὶ συλλάμβανε· αἶρε γὰρ τὸ ἄροτρον καὶ φέρε αὐτὸ πρὸς τὸν ἀγρόν. ἐγὼ γὰρ ἐλαύνω τοὺς βοῦς. ἀλλὰ σπεῦδε· μικρὸς μὲν γάρ ἐστιν ὁ ἀγρός, μακρὸς δὲ ὁ πόνος.”"
