      "ἔπειτα τὸν δοῦλον καλεῖ καὶ λέγει·",
      "“ὦ Ξανθία, ἐγὼ μὲν καλῶ σε· διὰ τί οὐκ ἐκβαίνεις ἐκ τοῦ οἴκου; μὴ κάθευδε, ἀλλὰ σπεῦδε πρὸς τὸν ἀγρόν. ἀλλὰ λάμβανε τὸ ἄροτρον καὶ φέρε πρὸς τὸν ἀγρόν. χαλεπὸς γάρ ἐστιν ὁ πόνος καὶ μακρός, σὺ δὲ καθεύδεις ἐν τῷ οἴκῳ καὶ οὐ πονεῖς· ἐγὼ δὲ πονῶ πολὺν χρόνον καὶ μάλα κάμνω. ἐλθὲ οὖν δεῦρο, καὶ συλλάμβανε.”",
