      "ὁ δὲ Δικαιόπολις τὰς ἐλαίας πιέζει καὶ ἔλαιον ποιεῖ.",
      "τέλος δὲ ὁ Δικαιόπολις μάλα κάμνει καὶ οὐκ ἐθέλει πονεῖν.",
      "ἡ οὖν γυνὴ τὸν ἄνδρα καλεῖ καί, “ἔπαιρε σεαυτόν, ὦ ἄνερ.” φησίν·",
