      "ἔπαιρε σεαυτόν· καιρὸς γάρ ἐστι βαδίζειν πρὸς τὸν ἀγρόν.”",
      "ὁ δὲ Δικαιόπολις μάλα κάμνει καὶ οὐκ ἐθέλει ἐπαίρειν ἑαυτόν·",
