      "ἡ δὲ γυνή, “ἀλλ᾿ οὐ δυνατόν ἐστιν,” φησίν, “ἔτι καθεύδειν· καιρὸς γάρ ἐστι πονεῖν. ἔπαιρε σεαυτόν, ὦ ἀργέ.”",
      "ὁ μὲν οὖν Δικαιόπολις μόλις ἐπαίρει ἑαυτὸν καὶ βαδίζει πρὸς τὸν ἀγρόν, ἡ δὲ Μυρρίνη καὶ ἡ Μέλιττα πρὸς τὴν κρήνην βαδίζουσιν (ἡ Μέλιττα θυγάτηρ ἐστίν, κόρη μάλα καλή).",
