      "ἡ δὲ Μέλιττα, “μὴ ἀγανάκτει,” φησίν, “ὦ μῆτερ· σπεύδω γὰρ ἐγὼ πρὸς τὴν κρήνην.”",
      "ἡ κόρη οὐδὲν ἄλλο λέγει, ἀλλὰ τὴν ὁδὸν διατρέχει.",
