      "ἡ δε Μέλιττα, “χαίρετε,” φησίν· “ἡ μήτηρ κελεύει με ἄλλην ὑδρίαν φέρειν,” καὶ τὴν ὑδρίαν γεμίζει.",
      "αἱ δέ, “διὰ τί,” φασίν, “ἡ μήτηρ κελεύει σε ἄλλην ὑδρίαν φέρειν; ἆρ᾿ οὐχ ἅλις ὕδατος ἔχει ἐν τῇ οἰκίᾳ;”",
      "ἡ δὲ Μέλιττα τῶν γυναικῶν ἀκούει ἀλλ᾿ οὐδὲν λέγει·",
