      "ἐπεὶ δὲ τὴν ὑδρίαν γεμίζει, οἴκαδε βαδίζει.",
      "μεγάλη δέ ἐστιν ἡ ὑδρία· ἡ οὖν Μέλιττα βραδέως βαδίζει.",
      "δι᾿ ὀλίγου δὲ κόρη τις, ὀνόματι Παμφίλη, αὐτὴν διώκει καὶ καλεῖ·",
