      "δι᾿ ὀλίγου δὲ ἡ Παμφίλη μάλα κάμνει καί, “μεγάλη ἐστὶν ἡ ὑδρία καὶ μόλις δυνατόν ἐστιν αὐτὴν φέρειν.",
