      "And the Athenians are now holding a festival.”",
      "And Melitta says, “The women at the spring say this too;",
      "for a messenger has come from the city.",
      "My mother and I intend to watch the festival, but father rarely wants to go to the city;",
      "but it is easy to persuade him.",
      "But tell me about the city and about the festival.”",
      "And Nearra says, “Listen, then.”",
      "“Many people are crossing the sea, wanting to watch the festival.",
      "And not only do many people come from the sea and from Piraeus, but also from the fields around the city.",
      "And on the sea there are many ships, and from the ships many people continually disembark.",
      "Everywhere indeed there is uproar in Piraeus.”",
      "And Melitta says, “But why did you go down to Piraeus?”",
      "And Nearra says, “My father made an agreement with a certain stranger.",
      "How beautiful all the places around Athens are;",
      "for not only does a beautiful sea wash the shore, but there is also much grain and sheep and fruit-bearing trees, and much wine, many figs, and much oil.",
