      "Then we went up to the city;",
      "Melitta, what a crowd of people, what an uproar, what shouting!",
      "And the marketplace is big, not small like in the village.",
      "There are many shops in the marketplace, and many workshops in the streets not far from the marketplace;",
      "for in the small villages, as in ours, the same men make a bed, a door, a plough, a table, and often build houses too;",
      "but in Athens one man makes beds, another tables, another doors.”",
      "And Melitta says, “Nearra, it is time for me to go to the house.",
      "But follow me, if you are free, and tell me everything about the city.”",
      "So the girls walk together, and talk to one another.",
      "When they reach the house, Melitta says, “Farewell, Nearra; I intend to persuade my father.",
      "For I too want to go to the city, and to watch the festival and many other things.”",
      "And Nearra says, “Farewell to you too, Melitta,” and departs.",
      "And Melitta goes into the house and looks for a water-jar.",
      "And there is a table in the house, and on the table there is a water-jar.",
