      "And others are departing from the spring, and hurrying toward their houses.",
      "When Melitta approaches, they call to her and say, “Greetings, Melitta; what are you doing? Why are you hurrying to the spring again?”",
      "And Melitta says, “Greetings; my mother orders me to bring another water-jar,” and fills the water-jar.",
      "And they say, “Why does your mother order you to bring another water-jar? Doesn’t she have enough water in the house?”",
      "And Melitta listens to the women but says nothing;",
      "for she does not want to tell them that she dropped the water-jar.",
      "When she fills the water-jar, she walks home.",
      "And the water-jar is big; so Melitta walks slowly.",
      "And after a little while a certain girl, named Pamphile, chases after her and calls:",
      "“Wait, friend; for I am about to help you;",
