     "lines_en": [
      "When both Philip and his grandfather approach the sheepfold, they hear a great noise;",
      "for Argus is barking fiercely, and the sheep are making a great uproar.",
      "So they hurry; for they want to know what is happening to the sheep.",
      "So the boy arrives first, and look — Argus stands by the road barking fiercely, and a big wolf comes down from the mountain toward the sheepfold.",
      "So Philip shouts loudly and takes stones and throws them at the wolf;",
      "and Argus rushes at him and attacks so fiercely that the wolf turns around and flees.",
      "So the dog chases him, and Philip hurries after him.",
      "And the grandfather has already come to the top of the mountain and sees the wolf and shouts:",
      "“Come here, Philip; don’t chase him but come back.”",
      "And now Argus seizes the wolf with his teeth and holds him, and Philip is already there and takes his knife and strikes the wolf.",
      "And it struggles and falls to the ground.",
      "At this point the grandfather approaches and sees the wolf lying on the ground.",
      "So he is amazed and says, “Well done, boy; you are very brave.",
      "For the wolf is big and fierce.",
      "And you, Argus, are a good dog; for you guard the sheep well.",
      "And now, Philip, hurry home; for your mother surely wants to know where you are and what has happened to you.”",
      "When they approach the house, they see the mother.",
      "So the grandfather hurries to her and tells her everything.",
      "And she says, “Are you telling the truth?”",
      "“Well done, boy; you are very brave.",
      "But look, Melitta is approaching from the spring.",
      "Come here, Melitta, and listen; for Philip has killed a wolf.”",
      "So the grandfather tells everything again, and Melitta is very amazed and says that both Argus and Philip are very brave and strong.",
      "Then the mother says, “Now come here, dear, and sit down with us under the tree; for you are very tired.",
      "And you, Melitta, sit down too.",
      "So listen; for I want to tell you a fine story.”",
      "So the grandfather sleeps — for he is very tired — and the children sit down under the tree and listen;",
      "for they desire to hear the story."
     ],
