      "ἐνταῦθα δὴ πρῶτον μὲν τὰ ποίμνια ἀμέλγει, ἔπειτα δὲ πῦρ καίει.",
      "οὕτω δὴ τόν τ᾿ Ὀδυσσέα καὶ τοὺς ἑταίρους ὁρᾷ καί, ‘ὦ ξένοι,’ βοᾷ, ‘τίνες ἐστὲ καὶ πόθεν πλεῖτε;’",
      "“ὁ δ᾿ Ὀδυσσεύς, ‘ἡμεῖς Ἀχαιοί ἐσμεν,’ φησίν, ‘καὶ ἀπὸ τῆς Τροίας οἴκαδε πλέομεν.",
      "‘χειμὼν δὲ ἡμᾶς ἐνθάδε ἐλαύνει.’”",
      "“ὁ δὲ Κύκλωψ οὐδὲν ἀποκρίνεται ἀλλὰ ὁρμᾶται ἐπὶ τοὺς Ἀχαιούς·",
      "τῶν ἑταίρων δὲ δύο ἁρπάζει καὶ κόπτει πρὸς τὴν γῆν·",
      "ὁ δὲ ἐγκέφαλος ἐκρεῖ καὶ δεύει τὴν γῆν.”",
      "ἡ δὲ Μέλιττα, “παῦε, ὦ Φίλιππε,” φησίν, “παῦε· δεινὸς γάρ ἐστιν ὁ μῦθος.",
      "ἀλλ᾿ εἰπέ μοι, πῶς ἐκφεύγει ὁ Ὀδυσσεύς; ἆρα πάντας τοὺς ἑταίρους ἀποκτείνει ὁ Κύκλωψ;”",
