      "ὁ δὲ Φίλιππος· “τῇ ὑστεραίᾳ, ἐπεὶ πρῶτον ἀνατέλλει ὁ ἥλιος, ὁ Κύκλωψ τὸν λίθον ἐξαίρει ἐκ τῆς τοῦ ἄντρου εἰσόδου καὶ πάντα τά τε πρόβατα καὶ τὰς αἶγας ἐκπέμπει.",
