      "ἡ δὲ Μέλιττα, “ἀλλὰ διὰ τί,” φησίν, “ὁ Ὀδυσσεὺς καὶ οἱ ἑταῖροι αὐτοῦ οὕτω τοὺς χειμῶνας φοβοῦνται;",
      "ἆρα οὐ δυνατόν ἐστιν ἐν τοῖς χειμῶσι καταφεύγειν εἰς τοὺς λιμένας;",
