      "πολλάκις γὰρ αἱ νῆες ἤδη κατὰ θάλαττάν εἰσιν ὅτε οἱ χειμῶνες γίγνονται, καὶ μακράν εἰσι πάντες οἱ λιμένες·",
      "οὐκ οὖν δυνατόν ἐστιν εἰς τοὺς λιμένας καταφεύγειν.”",
      "ἡ δὲ Μέλιττα· “ἀλλὰ εἰ μὴ οἱ ἄνεμοι ἐξέρχονται ἐκ τοῦ ἀσκοῦ, πῶς οὐκ ἀφικνοῦνται ὁ Ὀδυσσεὺς καὶ οἱ ἑταῖροι εἰς τὸν λιμένα τὸν τῆς πατρίδος αὐτῶν;”",
      "ὁ δὲ Φίλιππος· “ἄκουε δή·",
      "ὁ μὲν Ὀδυσσεὺς καθεύδει, μάλα γὰρ κάμνει·",
      "οἱ δὲ ἑταῖροι αὐτοῦ ἀγνοοῦσι τί ἐν τῷ ἀσκῷ ἔνεστιν.",
      "οὕτως οὖν αὐτῶν τις λέγει τοῖς ἄλλοις·",
      "‘τί οὐ λύομεν ἡμεῖς τοῦτον τὸν ἀσκόν;",
      "ἀφικνούμεθα γὰρ εἰς τὸν τῆς πατρίδος λιμένα, ἀλλ᾿ οὐδὲν ταῖς γυναιξίν, οὐδὲν τοῖς υἱοῖς φέρομεν.",
      "ὁ δὲ Ὀδυσσεὺς ἐν τούτῳ τῷ ἀσκῷ κρύπτει πολλοὺς θησαυρούς.’”",
      "οἱ δὲ ἄλλοι αὐτῷ πείθονται καὶ τὸν ἀσκὸν λύουσιν.",
      "ὦ ἀγνόητοι·",
      "οἱ γὰρ ἄνεμοι πάντες ἐξέρχονται ἐκ τοῦ ἀσκοῦ, χειμών τε μέγας γίγνεται ἐν τῇ θαλάττῃ καὶ τὴν ναῦν ἀπὸ τῆς πατρίδος ἀποφέρει·",
      "ὁ μὲν οὖν Ὀδυσσεὺς ἐγείρεται καὶ ἐπαίρει ἑαυτόν, οἱ δὲ ἑταῖροι στενάζουσι καὶ βοῶσιν.”",
      "ἡ δὲ Μέλιττα· “σώφρων μέν ἐστιν ὁ Ὀδυσσεύς, οὐ σώφρονες δὲ οἱ ἑταῖροι αὐτοῦ, καὶ διὰ τοῦτο κακῶς ἀποθνῄσκουσιν·",
      "οἱ γὰρ θεοὶ τὸν σώφρονα ἄνδρα ἀεὶ σῴζουσιν, τοὺς δὲ μὴ σώφρονας τῶν ἀνθρώπων οὐ φιλοῦσιν.",
      "διὰ τοῦτο ἀεὶ ἡ μήτηρ φησὶν ὅτι ἐμὸν ἔργον ἐστὶ σωφρονεῖν.”",
      "ὁ δὲ Φίλιππος, “ναὶ μὰ Δία, ὦ Μέλιττα,” φησίν·",
