      "ἰδού, οἱ πατέρες τοῖς θ᾿ υἱοῖς καὶ ταῖς θυγατράσιν ἡγοῦνται εἰς τὴν ἑορτήν, ἐκ τῶν ἀγρῶν πορευόμενοι, ὥσπερ ἡμεῖς·",
