      "And Philip sees a sausage-seller pushing his way through the crowd and shouting his wares.",
      "So he calls his father and says, “Dear daddy, look, a sausage-seller is coming this way.",
      "Don’t you want to buy some food? For we’re very hungry.”",
      "So Dikaiopolis calls the sausage-seller and buys food.",
      "So in this way they sit in the colonnade, eating sausages and drinking wine.",
      "And after the meal Dikaiopolis says, “Come now, don’t you want to go up to the Acropolis and see the sacred sights?”",
      "Grandfather is very tired and does not want to go up,",
      "but the others leave him sitting in the colonnade, and, pushing their way through the crowd, go up to the Acropolis.",
      "And when they reach the top of the Acropolis and pass through the gateway, they see the temple of the Maiden Goddess opposite, and the statue of Athena, which is huge, armed and holding a spear in her right hand.",
