      "The heralds lead the way;",
      "then maidens walk along most beautifully, carrying baskets full of grape-clusters.",
      "And following them are many citizens carrying wineskins, and many resident foreigners carrying bowls.",
      "Then the priest of Dionysus advances, and along with him the finest young men, carrying the statue of Dionysus.",
      "And last of all come the attendants, leading the sacrificial animals.",
      "So everyone follows the procession, rejoicing, to the god’s sanctuary.",
      "And when they arrive, the priest and the young men carry the god’s statue into the temple, and the attendants lead the sacrificial animals to the altar.",
      "Then the herald, making proclamation to the people, says, “Keep silence, citizens.”",
      "So the whole crowd falls silent and stays still.",
      "And the priest, raising his hands to the sky, says, “Lord Dionysus, hear me as I pray;",
      "“Roarer, receive our sacrifice, and be gracious to the people;",
      "for you, being gracious, keep the vines safe and swell the grape-clusters, so as to provide us with wine.”",
      "And all those present shout:",
      "“Eleleu, iou, iou, Roarer, being gracious, swell the grape-clusters and provide us with wine!”",
      "Then the priest slaughters the sacrificial animals;",
