      "And when everything is ready, the priest pours a libation of wine and prays to the god.",
      "At that point everyone drinks the wine and eats the meat, delighting in the feast.",
      "It is now midnight, and many of those present, having drunk too much, are reveling.",
      "So Myrrhine, afraid for the children, says, “Come now, husband; grandfather is very tired.",
