      "ὁ δὲ Δικαιόπολις, “θάρρει, πάππα,” φησίν, καὶ ἡγεῖται αὐτοῖς ἄνω καὶ θρᾶνον εὑρίσκει ἐν ἄκρῳ τῷ θεάτρῳ.",
      "ἐπεὶ δὲ πρῶτον καθίζονται, ὁ σαλπιγκτὴς προχωρεῖ καὶ σαλπίζει, τοὺς πολίτας κελεύων εὐφημεῖν.",
      "ἔπειτα δὲ ὁ τοῦ Διονύσου ἱερεὺς τῷ βωμῷ προσχωρεῖ καὶ σπονδὴν ποιεῖται, τῷ θεῷ εὐχόμενος·",
