      "ὁ δὲ Ὀδυσσεύς, “μὴ βλάπτετε τοὺς βοῦς,” φησίν· “εἰσὶ γὰρ τῷ Ἡλίῳ.”",
      "οἱ δὲ οὐ πείθονται αὐτῷ ἀλλ᾿ ἀποκτείνουσι τοὺς βοῦς.",
      "ὁ μὲν οὖν Ἥλιος τῷ πατρὶ Διὶ εὐχόμενος, “Ζεῦ πάτερ,” φησίν, “οἱ τοῦ Ὀδυσσέως ἑταῖροι τοὺς ἐμοὺς βοῦς ἀποκτείνουσιν.",
      "τιμώρει οὖν αὐτούς. εἰ δὲ μή, οὐδέποτε αὖθις ἐν τοῖς ἀνθρώποις λάμψω.”",
      "ὁ δὲ Ζεὺς ἀκούει αὐτοῦ εὐχομένου·",
      "ἐπεὶ γὰρ ὅ τε Ὀδυσσεὺς καὶ οἱ ἑταῖροι ἀποπλέοντες τὴν νῆσον λείπουσιν, χειμῶνα δεινὸν πέμπει καὶ τὴν ναῦν κεραυνῷ πλήττει.",
      "πάντες οὖν οἱ ἑταῖροι ἐκ τῆς νεὼς ἐκπίπτουσι καὶ ἀποθνῄσκουσιν· μόνος δὲ ὁ Ὀδυσσεὺς ἐκφεύγει, τοῦ ἱστοῦ λαμβανόμενος."
