     "lines_en": [
      "And Odysseus still suffers many terrible things, hastening to return to his native land.",
      "For he barely escapes the Sirens, and sailing past Sicily he falls into the greatest danger.",
      "For on one side is Scylla, a terrible monster with six heads, who, darting out from a certain cave, seizes and eats those sailing past;",
      "and on the other is Charybdis, a very terrifying whirlpool, which swallows everything.",
      "And Odysseus, fleeing Charybdis, sails close past Scylla; and she, darting out from the cave, seizes six of his companions; but Odysseus saves the rest.",
      "After a little while they arrive at a certain other island; and there they find many cattle;",
      "and his companions want to kill them and eat them.",
      "And Odysseus says, “Don’t harm the cattle; for they belong to Helios.”",
      "But they don’t obey him, and kill the cattle.",
      "So Helios, praying to his father Zeus, says, “Father Zeus, Odysseus’s companions are killing my cattle.",
      "So punish them. But if not, I will never again shine among men.”",
      "And Zeus hears him praying;",
      "for when Odysseus and his companions, sailing off, leave the island, he sends a terrible storm and strikes the ship with a thunderbolt.",
      "So all the companions fall out of the ship and die; but Odysseus alone escapes, taking hold of the mast."
     ],
