      "ἡ δὲ Μυρρίνη, ἐπεὶ ἔμαθεν ὅτι τυφλός ἐστιν ὁ παῖς, δακρύουσα τῷ ἀνδρί, “ὦ Ζεῦ,” ἔφη, “τί δεῖ ἡμᾶς ποιεῖν;",
      "τοῖς θεοῖς εὔχου βοηθεῖν ἡμῖν.”",
      "ὁ δὲ Δικαιόπολις, “ἀλλὰ δεῖ ἡμᾶς τὸν παῖδα φέρειν παρὰ ἰατρόν τινα,” ἔφη· “ἀλλ᾿ ἑσπέρα ἤδη γίγνεται.",
      "νῦν οὖν δεῖ πρὸς τὴν τοῦ ἀδελφοῦ οἰκίαν σπεύδειν καὶ αἰτεῖν αὐτὸν ἡμᾶς δέχεσθαι.",
      "αὔριον δὲ δεῖ ζητεῖν ἰατρόν.”",
      "βραδέως οὖν τῷ παιδὶ ἡγούμενοι βαδίζουσι πρὸς τὴν τοῦ ἀδελφοῦ οἰκίαν.",
      "ἐπεὶ δ᾿ ἀφίκοντο, ὁ μὲν Δικαιόπολις ἔκοψε τὴν θύραν.",
      "ὁ δὲ ἀδελφὸς πρὸς τὴν θύραν ἐλθὼν καὶ τὸν Δικαιόπολιν ἰδών, “χαῖρε, ὦ ἄδελφε,” ἔφη· “πῶς ἔχεις;",
      "σὺ δέ, ὦ Μυρρίνη, χαῖρε καὶ σύ.",
      "ἀλλ᾿ εἴπετέ μοι, τί πάσχετε;",
      "διὰ τί οὐκ ἐπανέρχεσθε εἰς τοὺς ἀγροὺς ἀλλ᾿ ἔτι μένετε ἐν τῷ ἄστει;",
