      "ὁ δὲ Δικαιόπολις· “ἐγὼ μὲν καλῶς ἔχω, ὁ δὲ παῖς, ἰδού, τυφλὸς γὰρ γέγονεν· οὐδὲν ὁρᾷ.",
      "πάρεσμεν οὖν αἰτοῦντές σε ἡμᾶς δέχεσθαι.”",
      "ὁ δὲ ἀδελφὸς ἰδὼν τὸν παῖδα τυφλὸν ὄντα, “ὦ Ζεῦ,” ἔφη, “τί ποτε ἔπαθεν ὁ παῖς;",
