      "οὕτως εἰπὼν εἰσήγαγεν αὐτοὺς εἰς τὴν οἰκίαν· οἱ δὲ πάντα τὰ γενόμενα αὐτῷ εἶπον.",
      "ὁ δὲ τὴν γυναῖκα καλῶν, “ἐλθὲ δεῦρο,” ἔφη· “πάρεισι γὰρ ὅ τε Δικαιόπολις καὶ ἡ Μυρρίνη·",
      "ὁ δὲ Φίλιππος δεινὸν ἔπαθεν· τυφλὸς γὰρ γέγονεν.",
