      "σὺ δέ, ὦ ἄδελφε, ἐλθὲ δεῦρο.”",
      "ὅ τε οὖν Δικαιόπολις καὶ ὁ ἀδελφὸς εἰς τὸν ἀνδρῶνα εἰσελθόντες πολλὰ διαλέγονται σκοποῦντες τί δεῖ ποιεῖν.",
      "τέλος δὲ ὁ ἀδελφός, “ἅλις λόγων,” ἔφη· “ἐγὼ σοφὸν ἰατρὸν ἔγνωκα καὶ αὔριον, εἴ σοι δοκεῖ, κομιῶ ὑμᾶς παρ᾿ αὐτόν.",
