     "lines_en": [
      "And Myrrhine, when she learned that the boy was blind, weeping, said to her husband, “O Zeus, what must we do?",
      "Pray to the gods to help us.”",
      "And Dicaeopolis said, “But we must carry the boy to some doctor; but it is already getting to be evening.",
      "So now we must hurry to my brother's house and ask him to receive us.",
      "And tomorrow we must look for a doctor.”",
      "So, leading the boy, they walk slowly to the brother's house.",
      "And when they arrived, Dicaeopolis knocked on the door.",
      "And the brother, having come to the door and seen Dicaeopolis, said, “Greetings, brother! How are you?",
      "And you, Myrrhine, greetings to you too.",
      "But tell me, what's the matter with you?",
      "Why are you not going back to the farm, but are still staying in the city?",
      "For it's already getting to be evening.”",
      "And Dicaeopolis said, “I myself am well, but the boy — look! — he has become blind; he sees nothing.",
      "So we have come asking you to receive us.”",
      "And the brother, seeing that the boy was blind, said, “O Zeus, whatever has happened to the boy?",
      "Come in and tell me what happened.”",
      "Having said this, he led them into the house; and they told him everything that had happened.",
      "And he, calling his wife, said, “Come here; for both Dicaeopolis and Myrrhine are here;",
      "and Philip has suffered something terrible; for he has become blind.",
      "So take him and the women into the women's quarters.",
      "And you, brother, come here.”",
      "So Dicaeopolis and the brother, having gone into the men's quarters, talk a great deal, considering what must be done.",
      "And at last the brother said, “Enough talk; I know of a wise doctor, and tomorrow, if you please, I will bring you to him.",
      "But now — for it is late — we must sleep.”"
     ],
