      "πολλάκις δὲ οἱ θεοὶ παρέσχον τοῖς ἀνθρώποις ἀγαθόν τε καὶ κακὸν ἅμα, ὥσπερ τῷ Ὁμήρῳ τῷ ποιητῇ·",
