      "ἔπειτα ὁ Χαιρεφῶν ὁ προβαίνων ἐξαίφνης ἔπταισεν· κατέπεσε δὲ εἰς χάσμα τι τῆς γῆς, καὶ ἀκίνητος ἔμεινεν.",
      "ἐγὼ δέ, βοηθεῖν βουλόμενος αὐτῷ πεσόντι, τὰς λαμπάδας ἀπέβαλον· αἱ δὲ πεσοῦσαι ἔσβησαν.",
      "“πανταχοῦ σκότος ἐξαίφνης ἐγένετο περὶ ἡμῶν.",
      "φόβος δὲ ἔλαβεν ἡμᾶς τότε μέγας.",
