      "ὁ δὲ κύων ὀσφραινόμενος τὴν ὁδὸν ηὗρε καὶ οἴκαδε ἐπανῆλθεν.",
      "ἐν δὲ τούτῳ ἡμεῖς μάλα φοβούμενοι μόλις ἐν τῷ σκότῳ προχωρεῖν οἷοί τ᾿ ἐγενόμεθα.",
      "ὦ παῖ, οὐδενὶ πώποτε τοσαύτη συμφορὰ ἐγένετο ὅση ἡμῖν τότε, ὡς ἐμοὶ δοκεῖ.”",
      "ὁ δὲ Φίλιππος, “ἆρα καὶ ὑμεῖς,” ἔφη, “οἷοί τε ἐγένεσθε τὴν τοῦ ἄντρου εἴσοδον εὑρεῖν;”",
      "“οὐδαμῶς,” ἔφη ἡ μήτηρ, “οὐ γὰρ ἱκανοὶ ἐγένοντο διὰ τὸν σκότον πορεύεσθαι καὶ τὴν ὁδὸν εὑρεῖν.”",
