      "τέλος δὲ τοῦ κυνὸς ὑλακτοῦντος ἀκούομεν· ὁ δὲ πατὴρ ἡμῶν καλεῖ ἡμᾶς βοῶν.",
      "εἴδομεν δὲ μετ᾿ οὐ πολὺν χρόνον λαμπάδος φῶς, καὶ τὸν πατέρα εἰσελθόντα.",
      "ἰδὼν γὰρ τοὺς λίθους λελειμμένους ἐν τῇ ὁδῷ καὶ τῷ κυνὶ ἑπόμενος ηὗρε τὸ ἄντρον.",
