     "lines_en": [
      "But Philip does not want to sleep; for weeping he says, “Alas, wretched me — who became responsible for this misfortune of mine?",
      "No doubt some one of the gods; for when I raised myself up in the road, having become blind, I suddenly learned that the gods hate me.",
      "Why did I not die then?",
      "For I do not want to be blind my whole life.",
      "O dear daddy, O mommy, help me, who have suffered these things.”",
      "And his mother, wanting to comfort and encourage the boy, and taking hold of his hand, says, “Take heart, dear boy, and do not weep;",
      "for I and your father are here for you.",
      "Do not say that the gods hate you; for often sufferings have become lessons for men.",
      "And often the gods have granted men a good and an evil at the same time, just as they did to the poet Homer;",
      "for he himself became blind, but the Muse granted him a beautiful voice, loving him very much.",
      "But do not be afraid, child; for both your father and I want to bring you to the doctor.”",
      "And Philip said, “But who is a doctor now in the city?",
      "And if there are doctors, they want to take much money, and we do not have any.”",
      "And his father, answering, said, “Do not fear these things, child; for the doctors in the city, without taking much money, are going to help you.”",
      "And the brother, taking up the conversation, said, “You have available, Dicaeopolis, my own money, which is, I think, sufficient.",
      "Besides, I have many friends in Athens ready to lend me money.",
      "And you are brave, boy, and since you are brave, the gods are going to help you.",
      "For many brave young men have received wounds in battles, just as you received one.",
      "And the gods always help them, loving them very much.”",
      "And Philip said, “But often the brave have also died while doing such deeds.”",
      "And his mother said, “Do not talk nonsense, child, but listen to me.",
      "Do you know Chaerephon, your father's friend and companion?”",
      "“Yes, by Zeus,” said the boy, “for he has a farm not far from our house, and my father has often taken me there.”",
      "And Myrrhine said, “Do you know what misfortune he suffered while still a boy?”",
      "“Not I, mother,” said Philip, “but tell me.”",
      "“Listen, then. Chaerephon, while still a boy, once having gone forward a little way from his own farm, found a certain cave, such a one as Homer described.”",
      "And Philip, taking up the conversation, said, “Do you mean the cave of the Cyclops?”",
      "“Yes. So, having taken two companions, he went into the cave, wanting to look around at everything.”",
      "“And whom did he have as companions?” said Philip.",
      "“Having found the cave, he took us as companions,” said Dicaeopolis, taking up the conversation; “me and my brother, still being boys.”",
      "“What happened then? Tell me, daddy.”",
      "“Having taken torches, we all came together seeking the cave.",
      "And I, wanting to find the road again, left stones behind me as I walked.",
      "And having found the cave, we went in, as your mother told you.",
      "Am I telling the truth, brother?”",
      "And the brother said, “Of course.",
      "I took two torches, since you did not, holding small stones in your hands;",
      "and Chaerephon, thinking he was going into some kind of battle, just like Odysseus against the Cyclops, took a sword in his right hand, and held a torch in his left.",
      "So we went in into the darkness of the cave.”",
      "“We also took the dog with us, a great and fine animal, Cerberus by name.",
      "Do you not remember, brother? For he himself saved us from the danger.”",
      "“But you did not take food and water, as if you were setting out on a long journey,” his mother said, taking up the conversation, “and because of this there arose a great danger of your dying in the cave.",
      "For they took nothing, child, except the sword and the torches.”",
      "“And having gone forward,” said Dicaeopolis's brother, “we could scarcely see anything in the darkness of the cave, even though we had the torches.",
      "Then Chaerephon, who was going ahead, suddenly stumbled; and he fell down into some chasm in the ground, and remained motionless.",
      "And I, wanting to help him after he had fallen, threw away the torches; and having fallen, they went out.",
      "“Darkness suddenly came about all around us.",
      "And great fear seized us then.",
      "And we went down slowly into the chasm, although we could see nothing, wanting to know whatever had happened to Chaerephon after he fell.”",
      "“And we scarcely found him lying in the depths of the chasm.",
      "And after a little while he stirs and breathes.",
      "And finally he raises himself up and says, ‘Why is there darkness everywhere? Am I blind?’",
      "And your father said, ‘By no means; for you are not blind, but we are all like blind men in the darkness of the cave.",
      "For we no longer have torches.",
      "So we must walk in the darkness, if we want to find the entrance of the cave again.’",
      "“So I, being the oldest of all, became the leader of the others in the darkness.",
      "But you, Dicaeopolis, became responsible for the safety of us all.",
      "For your father, child, said to the dog, ‘Go on, then, Cerberus; find the way.’",
      "And the dog, sniffing, found the way and went back home.",
      "And meanwhile, being very afraid, we were scarcely able to go forward in the darkness.",
      "Child, never has so great a misfortune befallen anyone as befell us then, as it seems to me.”",
      "And Philip said, “Were you all able to find the entrance of the cave?”",
      "“By no means,” said his mother, “for they were not able to travel through the darkness and find the way.”",
      "“For the whole night,” said Dicaeopolis, taking up the conversation, “we went around the cave in a circle, unable to get out, as if we had fallen into a labyrinth.",
      "And at last we hear the dog barking; and our father is calling us, shouting.",
      "And after not much time we saw the light of a torch, and our father coming in.",
      "For, having seen the stones left in the road, and following the dog, he found the cave.",
      "But only then did we realize that Chaerephon was blind.",
      "For he saw nothing, neither the light, nor the dog, nor our father.",
      "“So, having taken hold of him, we drew him out of the cave, weeping and groaning, and led him to his house.",
      "“And his father, when he saw that his son had become blind, first groaned, and then said that we must take the boy to the temple of Asclepius.",
      "But we were not able to; so he himself took his son.",
      "And when he arrived at the god's shrine, leading his own son, first he led him to the sea and washed him.",
      "Then they went to the precinct of the god.",
      "There he laid the boy down, and on the next day he woke up seeing.",
      "And you have seen him now, seeing everything.",
      "And many other wonderful things of this kind have happened in the temple of Asclepius.”",
      "“So do not be afraid, dear boy,” said his mother; “for after a little while you too will see again.",
      "But now sleep quietly; for it is late.”"
     ],
