      "τῇ δὲ ὑστεραίᾳ, ἐπεὶ πρῶτον ἡμέρα ἐγένετο, τὰς γυναῖκας ἐν τῇ οἰκίᾳ λιπόντες ὅ τε Δικαιόπολις καὶ ὁ ἀδελφὸς τὸν Φίλιππον εἰς τὴν ὁδὸν ἤγαγον.",
