      "And the road was straight, running between the Long Walls;",
      "and there were many people on it, and many wagons, and many mules too, carrying loads either toward the city or from the city toward the harbor.",
      "And Dicaeopolis hurries through the crowd, wanting to arrive as quickly as possible.",
      "And Philip, although holding his father's hand, stumbled and fell to the ground.",
      "And his mother, having cried out, said, “O poor boy, what happened to you?” and, having run up, lifted him.",
      "And he, having suffered no harm, said, “Do not worry, mother; for although I have fallen, I am fine.”",
