      "And Dicaeopolis, watching everything, was at a loss what he must do and where he must look for some ship about to sail to Epidaurus;",
      "for he saw a great many ships riding at anchor by the mole.",
      "And at last they all sat down in a certain wine-shop and asked for wine.",
      "And while they were drinking the wine, a certain old sailor approached and said, “Who are you, friends, and with what purpose are you here?",
      "For, being countryfolk, you seem to be at a loss.",
      "Tell me what is the matter with you.”",
      "And Dicaeopolis, having explained everything, said, “Do you know whether there is any ship here about to sail to Epidaurus?”",
      "And he said, “Certainly; for my own ship is about to sail there.",
      "So follow me to the ship-captain.",
      "But look, here is the ship-captain himself, approaching at just the right moment.”",
      "And so saying, he led the way for them to a certain young man then disembarking from some ship.",
      "So Dicaeopolis, approaching, asked him whether he was willing to convey them to Epidaurus.",
      "And he said, “Certainly; I am willing to convey you there.",
      "But board quickly; for we are about to sail at once.”",
