      "And he said, “By no means; I ask four.”",
      "And Dicaeopolis said, “Look, three drachmas; for I am not able to offer more.”",
      "And he said, “So be it; give me the money, and board quickly.”",
      "So Dicaeopolis gave the money to the ship-captain and bade farewell to his wife and his brother.",
      "And Myrrhine, having wept, said, “Guard the boy well, dear husband, and hasten to return home as quickly as possible.",
      "And you, dearest boy, take heart, and with god's help return in a little while with healthy eyes.”",
