      "ἐπεὶ δὲ οὐκέτι ἐφαίνοντο αἱ τριήρεις, μείζων μὲν ἐγίγνετο ὁ ἄνεμος, ἡ δὲ θάλαττα ἐκύμαινεν.",
      "οἱ δ᾿ ἄνθρωποι οὐκέτι ἐτέρποντο, ἀλλ᾿ οἱ μὲν ἄνδρες ἐσίγων, αἱ δὲ γυναῖκες ἔκλαζον εὐχόμεναι τὸν Ποσειδῶ σῴζειν ἑαυτὰς εἰς τὸν λιμένα.",
      "ἀνὴρ δέ τις, ὃς ἐγγὺς τοῦ Δικαιοπόλιδος ἐκαθίζετο, ἀνέστη καὶ βοήσας, “ὀργίζεται ἡμῖν,” ἔφη, “ὁ Ποσειδῶν, ὡς δοκεῖ.",
      "κακὸν γὰρ ἄνθρωπον ἐν τῇ νηῒ φέρομεν, ὃν δεῖ ῥίπτειν εἰς τὴν θάλατταν.”",
      "καὶ τοὺς παρόντας ἐπιφθόνως ἐσκόπτει.",
      "ὁ δὲ γέρων προσελθών, “σίγησον, ὦ ἄνθρωπε,” ἔφη· “οὐδὲν γὰρ λέγεις.",
      "ἤδη γὰρ πίπτει ὁ ἄνεμος καὶ οὐκέτι τοσοῦτο κυμαίνει ἡ θάλαττα.",
      "κάθιζε οὖν καὶ ἥσυχος ἔχε.”",
      "τρεψάμενος δὲ πρὸς τὸν Φίλιππον, “μηδὲν φοβοῦ, ὦ παῖ,” ἔφη· “δι᾿ ὀλίγου γὰρ εἰς τὴν Σαλαμῖνα ἀφικνούμεθα.",
      "ἤδη γὰρ πλέομεν διὰ τῶν στενῶν πρὸς τὸν λιμένα.",
      "ἰδού, ὦ Δικαιόπολι, τὰ στενὰ ἐν οἷς τὸ τῶν βαρβάρων ναυτικὸν ἐμένομεν ὅτε τῇ Ἑλλάδι αὐτοὺς ἠμύνομεν ὑπὲρ τῆς ἐλευθερίας μαχόμενοι.”",
      "ὁ δὲ Δικαιόπολις, “τί λέγεις, ὦ γέρον;” ἔφη· “ἆρα σὺ ἐκείνῃ τῇ μάχῃ παρῆσθα;”",
      "ὁ δὲ γέρων, “μάλιστά γε,” ἔφη, “ἐγὼ παρῆν, νεανίας ὢν καὶ ἐρέτης ἐν τριήρει Ἀθηναίᾳ.”",
      "ὁ δὲ Φίλιππος· “ἆρα τὰ ἀληθῆ λέγεις; μάλα οὖν γεραιὸς εἶ, εἰ τῷ ὄντι ἐκείνῃ τῇ μάχῃ παρῆσθα.",
      "ἀλλ᾿ εἰπὲ ἡμῖν τί ἐγένετο.”",
      "ὁ δέ, “μακρός ἐστιν ὁ λόγος,” ἔφη, “καὶ εἰ βούλεσθε τὰ γενόμενα μαθεῖν, δεῖ με πάντα ἐξ ἀρχῆς ἐξηγεῖσθαι.",
      "ἐγὼ δέ, ὃς παρῆν, τέρπομαι ἐξηγούμενος.",
      "ἀκούετε οὖν.”"
