     "lines_en": [
      "And when they had sailed a little while, ten warships came into view, which were travelling toward the Piraeus, returning from the islands.",
      "So everyone watched the triremes, which were speeding quickly through the waves.",
      "For the rowers, obeying the boatswain, struck the sea together.",
      "And when the triremes were no longer in sight, the wind grew stronger, and the sea grew rough.",
      "And the people were no longer enjoying themselves, but the men fell silent, and the women shrieked, praying Poseidon to bring them safely to the harbor.",
      "And a certain man, who was sitting near Dicaeopolis, stood up and, having shouted, said, “Poseidon is angry with us, it seems.",
      "For we are carrying some evil man on the ship, whom we must throw into the sea.”",
      "And he mocked those present, spitefully.",
      "But the old man, coming forward, said, “Be quiet, fellow; for you are talking nonsense.",
      "For already the wind is dropping, and the sea is no longer so rough.",
      "So sit down, and be still.”",
      "And, turning toward Philip, he said, “Fear nothing, boy; for after a little while we shall arrive at Salamis.",
      "For already we are sailing through the strait toward the harbor.",
      "Look, Dicaeopolis — the strait in which we awaited the barbarians' fleet, when we defended Greece against them, fighting for freedom.”",
      "And Dicaeopolis said, “What do you mean, old man? Were you present at that battle?”",
      "And the old man said, “Certainly; I was there, being a young man and an oarsman on an Athenian trireme.”",
      "And Philip said, “Are you telling the truth? You must be very old indeed, if you were really present at that battle.",
      "But tell us what happened.”",
      "And he said, “It is a long story, and if you want to learn what happened, I must relate everything from the beginning.",
      "And I, who was there, take delight in relating it.",
      "So listen.”"
     ],
