     "lines_en": [
      "“First I want to tell you about the courage and daring of the Athenians.",
      "For I myself, being a sailor, am not able to make fine speeches;",
      "but, having been present at the deeds which I am now going to relate, I am able to make my words true ones, not false, as orators often do.",
      "For I, who was present, am going to reveal to you clearly the true cause which gave freedom to all the Greeks.",
      "So you must not trust the false opinion held both by the many and by the orators, but the true facts which I, in a true account, am going to relate to you.",
      "“And our fathers became our leaders and teachers in this — that the power of the Persians is not invincible, but that all numbers and all wealth yield to courage.",
      "So those men became fathers not only of our bodies, but also of our freedom;",
      "for it was by looking to their deeds that the Greeks dared to risk the later battles too for the sake of their safety, having become pupils of those who fought at Marathon.",
      "So we, who had spent our lives in complete freedom, considered that we must fight the barbarians for our freedom, on behalf of all the Greeks.",
      "“For our ancestors established a fine constitution — for a constitution is the true nurture of men, a fine one nurturing good men, and the opposite nurturing bad ones — but the constitutions of the other nations are tyrannies and oligarchies;",
      "so they dwell together, some considering the others slaves, others masters.",
      "But we do not think it right to be either slaves or masters of one another, but we seek equality before the law;",
      "for we are friends to one another, and all free, and we yield to nothing else except the true reputation of virtue.",
      "“But tyrants, and those raised under tyranny, are forever untasted of freedom and true friendship.",
      "For hubris ever seizes the souls of tyrants; and hubris, coming into flower, bears the fruit of Ruin, and from it men reap nothing else but tears and grief.",
      "For Zeus, who sees everything, punishes the hubris of tyrants, who, being mortal, dare to contend against the gods.",
      "“And we, like our ancestors who defeated the barbarians at Marathon, believing that a noble death leaves behind an undying report concerning good men, did not fear the multitude of the enemy, but trusted rather in our own courage.",
      "So in the dangers of the war, having abandoned the city, but having embarked on the triremes, we set our lives, few as they were, against the multitude of Asia.",
      "And we demonstrated to all mankind, by winning the sea-battle, that it is better to risk danger with few men for freedom, than to fight with many slaves for one's own slavery.",
      "“For Xerxes arrived with a very great number of triremes, and led so boundless a multitude of infantry that it is difficult even to list the nations that followed with him.",
      "And this is the greatest and truest sign of that multitude — although it was possible for him, with a thousand triremes, to ferry the infantry across from Asia into Europe, he was not willing to, but instead made a road through the sea.",
      "“So our fathers demonstrated to the Greeks that it was possible to defend themselves against the barbarians by land;",
      "but with triremes it was still uncertain, and the Persians had a reputation for being invincible at sea, both in number and in wealth and in skill and in strength.",
      "But we put a stop to those of the Greeks who feared the multitude of triremes and men.",
      "“For we did not want only to save the walls of our own city, but, considering the whole of Greece to be our fatherland, we helped all the other Greeks;",
      "and when the army of the barbarians approached our walls, it found no one in the city;",
      "for the gates of the walls stood open, and the men, neither on the walls nor in the streets, but aboard the triremes on the sea, awaited the enemy, having abandoned both their own houses and their temples;",
      "for, wanting to demonstrate that in dangers at sea too, just as in dangers on land, courage always prevails over numbers, they believed that men are truly a city, and not walls, nor triremes empty of men.",
      "For cities have need neither of walls nor of triremes, nor of numbers nor of size, without courage.",
      "For walls and houses and temples, without the courage of men, are like a lifeless body.",
      "“So we first drove the barbarians away from our land and from all of Greece, and then we set about rebuilding the city and the walls.",
      "And so our city put a stop to a power that was marching in hubris against all of Europe and Asia.",
      "But everything must be gone through from the beginning; so listen, since I am going to make my account a true one.”"
     ],
