     "lines": [
      "“ἐπεὶ ὁ Ξέρξης, βασιλεὺς ὢν τῶν Περσῶν, τὸν στόλον παρεσκεύαζεν, ἐν νῷ ἔχων πᾶσαν τὴν Ἑλλάδα καταστρέφεσθαι, οἱ τῶν Ἑλλήνων πρῶτοι συνῆλθον εἰς τὴν Κόρινθον καὶ ἐσκόπουν τί δεῖ πράττειν.",
      "πολὺν δὲ χρόνον ἠπόρουν· μείζονα γὰρ στρατὸν εἶχεν ὁ Ξέρξης ἢ πάντες οἱ Ἕλληνες καὶ πλέονας ναῦς.",
      "τέλος δὲ ἔδοξεν αὐτοῖς τοὺς βαρβάρους ἀμύνειν ἐν ταῖς Θερμοπύλαις·",
      "ἐκεῖ γὰρ κατὰ μὲν γῆν τὰ ὄρη οὕτω πρόσκειται τῇ θαλάττῃ ὥστε ὀλίγοι πρὸς πολλοὺς δύναται μάχεσθαι, κατὰ δὲ θάλατταν πόροι εἰσὶ στενοὶ ἐν μέσῳ τῆς τε Εὐβοίας καὶ τῆς ἡπείρου.",
      "μαθόντες οὖν οἱ Ἕλληνες ὅτι ὁ Ξέρξης ἤδη πρὸς τὴν Ἑλλάδα πορεύεται, τὸν Λεωνίδην ἔπεμψαν, βασιλέα ὄντα τῶν Λακεδαιμονίων, ἑπτάκις χιλίους [ἑπτακισχιλίους] ἔχοντα ὁπλίτας.",
      "οὗτοι δὲ ἀφικόμενοι εἰς τὰς Θερμοπύλας παρεσκευάζοντο ἀμύνειν τοὺς βαρβάρους τῇ Ἑλλάδι.",
      "ὁ δὲ Ξέρξης ἀφικόμενος εἰς τὰ στενὰ στρατὸν ἔχων μέγιστον δή, τέτταρας μὲν ἡμέρας ἡσύχαζεν·",
      "ἤλπιζε γὰρ τοὺς Ἕλληνας ἀποφεύξεσθαι ἰδόντας τὸ πλῆθος τοῦ στρατοῦ.",
      "τῇ δὲ πέμπτῃ ἡμέρᾳ—οἱ γὰρ Ἕλληνες ἔτι ἀκίνητοι ἔμενον—τὸν στρατὸν ἐκέλευσεν εὐθὺς προσβαλεῖν.",
      "οἱ δὲ Ἕλληνες ἀνδρειότατα μαχόμενοι τοὺς βαρβάρους ἤμυνον.",
      "τέλος δὲ βασιλεὺς τοὺς Πέρσας ἐπέπεμψεν οὓς ‘ἀθανάτους’ ἐκάλει, ἀνδρειοτάτους ὄντας τῶν στρατιωτῶν, ἐλπίζων τούτους γε ῥᾳδίως νικήσειν τοὺς Ἕλληνας.",
      "ἐπεὶ δὲ καὶ οὗτοι συνέβαλον, οὐδὲν ἄμεινον ἔπραττον ἢ οἱ ἄλλοι, ἐν τοῖς στενοῖς μαχόμενοι καὶ οὐ δυνάμενοι τῷ πλήθει χρῆσθαι.",
      "βασιλεὺς δὲ τὴν μάχην θεώμενος τρὶς ἀνέδραμεν, ὡς λέγουσιν, ἐκ τοῦ θρόνου, φοβούμενος ὑπὲρ τοῦ στρατοῦ.”"
     ],
     "lines_en": [
      "“When Xerxes, being king of the Persians, was preparing his expedition, having in mind to subdue all of Greece, the leading men of the Greeks came together at Corinth and considered what must be done.",
      "And for a long time they were at a loss; for Xerxes had a greater army than all the Greeks, and more ships.",
      "But finally it seemed best to them to ward off the barbarians at Thermopylae;",
      "for there, by land, the mountains lie so close against the sea that a few can fight against many, and by sea there are narrow channels between Euboea and the mainland.",
      "So the Greeks, learning that Xerxes was already marching toward Greece, sent Leonidas, king of the Lacedaemonians, having seven thousand hoplites.",
      "And these men, having arrived at Thermopylae, prepared to defend Greece against the barbarians.",
      "And Xerxes, arriving at the narrows with a truly enormous army, kept quiet for four days;",
      "for he hoped the Greeks would flee once they saw the size of his army.",
      "But on the fifth day — for the Greeks still remained unmoved — he ordered his army to attack at once.",
      "And the Greeks, fighting most bravely, fought off the barbarians.",
      "At last the king sent forward the Persians whom he called ‘Immortals,’ the bravest of his soldiers, hoping that these at least would easily defeat the Greeks.",
      "But when these too joined battle, they fared no better than the others, fighting in the narrows and unable to make use of their numbers.",
      "And the king, watching the battle, leapt up three times, as they say, from his throne, fearing for his army.”"
     ],
