     "lines_en": [
      "And while Dicaeopolis and Philip and the sailor were talking, suddenly they heard men on the ship shouting loudly.",
      "For two men, quarreling with each other, were raising their voices very loud.",
      "The one said, “No, by Zeus, you will not get away with saying that!” and the other, answering, said, “Go to the crows!”",
      "And everyone on the ship, hearing these shouts and this uproar, drew near to the quarreling men, wanting to know the cause of this dispute.",
      "The men, laughing, kept saying, “Hit him, hit the rascal!” while the women, shrieking, kept saying, “Stop them, stop the men quarreling!”",
      "And Dicaeopolis said, “What is it? What is this uproar? What is this business? And who are the ones shouting?”",
      "And the old sailor said, “I don't know; but we must find out what is happening. Come now, come with me.” And having said this, he raised himself up and walked toward the quarreling men.",
      "And the helmsman, running up, said, “Heracles! What is this? Whatever is this trouble? By Poseidon, you're mad, it seems to me. Stop, stop quarreling with each other, and tell me from the beginning where this quarrel of yours came from.”",
      "So the one man said, “This fellow, at first, was saying many bad things in a loud voice, and then he even struck me, and made such a shouting and uproar that both you and all these others came. This man is mad, it seems to me.”",
      "And the other, breaking in, said, “Tell me, worst of all men — do you dare to say this while even looking me in the face?”",
      "And he, answering, said, “Be silent, you rascal! For you took a stick against me — a free man — and struck me. Is this not great insolence?”",
      "And the other said, “Yes, by Zeus, and I did well to strike you, since you are not only a thief but also a spy of the Lacedaemonians, and not really an Athenian merchant.”",
      "And he said, “What do you say, men? Is this rascal not insulting me?”",
      "And the other said, “Will you be quiet? Listen, helmsman; for this was the beginning of the quarrel. This man did such things for which he is now justly hated by me. And all of you too, men of Athens, must hear this whole business.",
      "For this man is not an Athenian merchant, as he wishes to appear, but, being a spy of the Lacedaemonians, lives in our city plotting against us.",
      "For this man's father was a foreigner, and was not able to speak good Attic; and I saw this very man and a certain stranger conversing in Doric in the marketplace.",
      "And just now I heard him speaking on behalf of the Lacedaemonians; for he was saying that the city of the Spartans is stronger than ours, and that the Lacedaemonians have always been braver than the Athenians in battles, and that the Lacedaemonians are the most prudent of all the Greeks and far more prudent than the Athenians, and many other such things.”",
      "And the helmsman said, “You worst and most wicked of men, do you dare to say these things to us!”",
      "And the merchant, very frightened, said, “Not at all, helmsman. I myself hate the Lacedaemonians very much.",
      "And I am well aware that the Athenians are the best of the Greeks, holding the empire of the sea and sailing more triremes than the Lacedaemonians;",
      "for they have a greater army than we do by land, but far fewer ships and sailors.",
      "For no one is unaware that the Athenians are better in seamanship than all the other Greeks.",
      "I was only saying this: that the Laconians, at whom we are always indignant, are not responsible for all our troubles.",
      "And how am I not most truly an Athenian? For I am your fellow citizen, friends, being Athenian both on my father's side and on my mother's side;",
      "for this man slanders my father, since he was a foreigner;",
      "for he, in war, having been captured by the enemy, became a slave, and remained a long time in a foreign land, and because of this was no longer able to speak good Attic.",
      "But he really was a citizen, and not a foreigner, as this man foolishly claims, since his father Charisius and his mother are Athenians.",
      "And about my mother I want to say this to you: I had a grandfather, men of Athens, my mother's father, who was one of those who campaigned and died at Marathon, and that man's brother died at Salamis, campaigning under Themistocles.",
      "And you heard this man saying that he saw me in the marketplace conversing with some stranger in Doric.",
      "Well, what of it? For being a merchant, I have often set out from this city, and from this sea I have sailed to many other lands, and I have seen the cities of many men and come to know their minds, just as Homer says about Odysseus.",
      "So it is nothing strange that I have also learned the dialects of very many peoples.",
      "So do not believe this man, helmsman, who is telling lies and slanders.",
      "And to you, men, why must I say more? For I think that now you are ignorant of nothing, since you have heard the truth.”",
      "And the helmsman said, “Now then, be quiet, and do not make an uproar, nor fight with one another; for we must sail quietly and reach Epidaurus. So you, merchant, do not speak on behalf of the Lacedaemonians, and you, sailor, do not be angry, but keep calm.” Having said this, he went away, and shortly afterward all the others sat down too.",
      "And Dicaeopolis said, “Look, old man, how great a change of affairs there is in this our country. You were telling us how all the Greeks, both the Lacedaemonians and the Athenians, fought together against the barbarians for freedom; but now men living in the very same city hate one another, and go looking for some cause of hatred and strife.",
      "For then the Greeks considered the whole of Greece to be their common fatherland, but now they care only for their own households.",
      "So our ancestors preserved both their concord toward the Greeks and their hostility toward the barbarians; for concord seemed to be the greatest good for cities.",
      "But now not only do the Athenians hate the Lacedaemonians and the Lacedaemonians hate the Athenians, but the Athenians themselves are hostile to one another.",
      "Alas, alas for this city!”",
      "And Philip, taking up the conversation, said, “I want to hear how the Athenians fought against the barbarians at Salamis. So do not stop your story, sailor, but tell us what happened when the barbarians were lying at anchor in the harbor.”",
      "And the sailor said, “Be quiet then, and listen.”"
     ],
