      "ψόφον δὲ ἀκούοντες ἔμαθον ὅτι ἀνέβησαν οἱ Πέρσαι.",
      "ἔδραμον οὖν οἱ Ἕλληνες καὶ ἐνέδυον τὰ ὅπλα, καὶ εὐθὺς παρῆσαν οἱ βάρβαροι.",
