      "ὁ μὲν οὖν Ὑδάρνης διέταξε τοὺς Πέρσας εἰς μάχην· οἱ δὲ Ἕλληνες ἐλπίζοντες τοὺς βαρβάρους ἐν νῷ ἔχειν προσβαλεῖν, ἔφυγον εἰς τὸν τοῦ ὄρους κόρυμβον καὶ παρεσκευάζοντο μαχόμενοι ἀποθανεῖν.",
