     "lines_en": [
      "“So the Athenians were in very great perplexity; but Themistocles persuaded them not to yield to the barbarians but to fight for their freedom.",
      "So they conveyed the women and the children and the old men to the Peloponnese and to Salamis, abandoning Attica and the city to the enemy.",
      "And they themselves, having embarked on the ships, sailed to Salamis and prepared to fight by sea.",
      "And meanwhile the generals of the Greeks, having come together at Salamis, were so afraid that they wanted to flee to the Peloponnese;",
      "but Themistocles, standing up in the council, said that even now they could defeat the enemy;",
      "for fighting in the narrows the barbarians would not be able to make use of their numbers; so they must force them to join battle there.",
      "Having said this, he not only persuaded the other generals to fight, but also secretly sent a messenger to Xerxes, saying that the Greeks were preparing for flight.",
      "So Xerxes, when he learned that the Greeks intended to flee, wanting to destroy them as quickly as possible, resolved to force them to fight at Salamis.",
      "So of his ships he sent some around the island, ordering the admirals to guard the exits, and he ordered others to guard the straits, so that it was no longer possible for the Greeks to sail away.”"
     ],
