     "lines_en": [
      "“So for the whole night the barbarians rowed this way and that, guarding both the straits and the exits, while the Greeks kept quiet, preparing to fight.",
      "And as soon as day came, the barbarians advanced into the straits, trusting that they were going to defeat the Greeks easily, but suddenly they heard a very great shout, so that they were extremely afraid.",
      "For the Greeks, using good order, advanced into battle, and sailing against the barbarians, shouted the paean.",
      "And thus Aeschylus the poet, who was himself also present at the battle, represents the Greeks sailing against the barbarians:",
      "“First the right wing led the way in good order, in due array, and second the whole fleet advanced, and at the same time one could hear a great shout: ‘O sons of the Greeks, go, free your fatherland, free your children, your wives, the seats of your ancestral gods, and the tombs of your forebears — now the struggle is for all.’”",
      "“So in this way the Greeks attacked the Persian force, and, clashing in the narrows, fought a sea-battle, few against many.",
      "And the barbarians, although they had very many ships, were not able to make use of all their ships at once.",
      "And the Greeks either damaged or sank the foremost of the barbarians' ships, attacking with such vigor that the barbarians, thoroughly frightened, turned and tried to flee.",
      "Then indeed a very great uproar arose.",
      "For the barbarians' ships kept colliding with one another, some trying to escape from the battle, others advancing into it.",
      "And at last all the barbarians fled, using no order at all, and the Greeks, pursuing, sank a very great many ships;",
      "and everywhere there was wreckage, and everywhere corpses, so that it was no longer possible to see the sea.",
      "So they fought in this way until night fell.",
      "“And meanwhile Xerxes was sitting on a certain hill near the sea, watching the battle;",
      "for he trusted that the Persians would easily win; for he was ignorant of the ways of fortune, and did not know what the gods had in mind, but always dealt in insolence.",
      "And realizing that the Greeks were winning, and the barbarians were fleeing, he stood up and tore his robes.",
      "For he was in great perplexity; for having lost his fleet, he was no longer able to supply provisions for his infantry, which was very great.",
      "So he ordered his generals to lead the infantry by land toward Asia, while he himself fled, lamenting.",
      "So in this way the Greeks, having defeated the Persians, freed Greece.",
      "And indeed in this action the Athenians supplied the most ships of the Greeks and displayed the greatest courage, so that it is truly possible to say that the Athenians saved Greece, and not least Themistocles, who, being an Athenian general, was most responsible for the victory.",
      "This epigram was written by Simonides, who was an excellent poet, for the Athenians who died in this war:",
      "“If to die nobly is the greatest part of excellence, fortune allotted this to us above all others. For hastening to bestow freedom on Greece, we lie here, possessed of praise that never grows old.”"
     ],
