      "τῷ δὲ ἐπιγιγνομένῳ ἔτει πανταχόσε τοῦ Αἰγαίου πόντου πλέοντες τοὺς βαρβάρους ἐξηλάσαμεν· τήν τε γὰρ Κύπρον ἐλευθερώσαμεν καὶ πρὸς τὸν Πόντον πλεύσαντες τό τε Βυζάντιον εἵλομεν καὶ ἄλλας πόλεις πολλάς· οὐδαμοῦ γὰρ ἡμῖν ἀντέχειν ἐδύναντο οἱ βάρβαροι.",
      "“ὕστερον δέ, ὡς οἱ Πέρσαι στρατόν τε μέγιστον καὶ ναῦς διακοσίας συναγείραντες εἰς τὸν Αἰγαῖον πόντον αὖθις εἰσβιάζεσθαι ἐπειρῶντο, ὁ Κίμων, στρατηγὸς ἄριστος ὤν, ἡμῖν ἡγούμενος κατέλαβεν αὐτοὺς παρὰ τῷ Εὐρυμέδοντι ποταμῷ καὶ ἐνίκησε κατὰ γῆν τε καὶ θάλατταν ἐν μάχῃ μεγίστῃ.",
      "“καὶ δὴ καὶ εἰς τὴν Αἴγυπτον ἐστρατεύσαμεν καὶ τοῖς ἐνοίκοις βοηθοῦντες τοὺς Πέρσας ἐξηλάσαμεν.",
