      "ἓξ οὖν ἔτη ἐν τῇ Αἰγύπτῳ ἐμένομεν καὶ πολλὰ θαύματα εἴδομεν· οἱ γὰρ Αἰγύπτιοι πάντα ἔμπαλιν τοῖς ἄλλοις ἀνθρώποις ποιοῦσι καὶ νόμοις ἀλλοίοις χρῶνται.",
