      "“τάς τε οὖν πυραμίδας ἐθεωρήσαμεν, σήματα μέγιστα ὄντα τῶν βασιλέων τῶν ἀρχαίων, καὶ τὴν Σφίγγα, εἰκόνα δεινοτάτην, τὸ μὲν ἥμισυ γυναῖκα, τὸ δε ἥμισυ λέαιναν.",
