     "lines_en": [
      "So having finished his story, the sailor lay down on the deck, and Dicaeopolis and Philip were silent, marveling at everything he had said.",
      "At last Philip said, “How bravely the Greeks fought, how splendidly the Athenians led their allies. But what did you do after the war? Did you become a merchant and sail in trading-ships?”",
      "And he said, “Not at all; for the war had not ended, but we still had to fight the barbarians for a long time. For the barbarians held all the islands and all Ionia.”",
      "And Philip said, “But how long did you have to fight? Were you present at many battles?”",
      "And the sailor, standing up and coming closer to him, said, “Very much so, my boy; I was present at very many battles, and sailed to many places on earth with the allies. And we always defeated the barbarians.”",
      "And Philip said, “But where on earth did you fight?”",
      "And he said, “First, just as spring was beginning, we brought freedom back to the Ionians; for sailing with a hundred ships to Samos, and chasing the barbarians' fleet to Mycale, we disembarked onto the land and both defeated their army and destroyed their fleet.",
      "And the Ionians, when they learned that we were winning, revolted from the Persians and came to our aid; so in this way they became free again.",
      "And in the following year, sailing everywhere over the Aegean sea, we drove out the barbarians; for we freed Cyprus, and sailing to the Pontus we took Byzantium and many other cities too; for nowhere were the barbarians able to hold out against us.",
      "“Later, when the Persians, having gathered a very great army and two hundred ships, tried to force their way again into the Aegean sea, Cimon, who was an excellent general, leading us, caught them by the river Eurymedon and defeated them by both land and sea in a very great battle.",
      "“And indeed we also campaigned into Egypt, and, helping the inhabitants, drove out the Persians.",
      "For we sailed up the Nile, a very great river, which waters all Egypt in summer and flows into the sea by seven streams; and we took Memphis, a great city lying on the Nile.",
      "So we remained in Egypt for six years and saw many marvels; for the Egyptians do everything the opposite way from other people, and follow different customs.",
      "For among the Egyptians, the women do the marketing, while the men stay at home and weave.",
      "“So we viewed the pyramids, which are very great tombs of the ancient kings, and the Sphinx, a most fearsome image, half woman and half lioness.",
      "And indeed we also saw strange animals: crocodiles, which of all mortal creatures grow from the smallest into the largest and most fearsome, and ostriches, certain very large birds, which cannot fly but run no more slowly than horses.",
      "But at last the Persians, having gathered a very great army, attacked us and drove us out of Memphis.",
      "So in this way we suffered our first very great disaster; for having lost two hundred ships, we ourselves barely escaped to Cyrene.”"
     ],
