      "ἡμεῖς οὖν λυπούμενοι οἴκαδε ἀπεπλεύσαμεν.",
      "τῷ δὲ ἐπιγιγνομένῳ ἔτει σπονδὰς ὁ δῆμος ἐποιήσατο βασιλεῖ.",
      "τοσαῦτα οὖν εἰργασάμεθα πρὸς τοὺς βαρβάρους μαχόμενοι.",
      "ἀγὼν οὖν μέγιστος πρόκειταί σοι, ὦ παῖ· δεῖ γάρ σε ἄξιον γίγνεσθαι τῶν πατέρων.”",
      "ὁ δὲ Φίλιππος, “ἀληθῆ λέγεις, ὦ γέρον,” ἔφη· “ἐὰν δὲ ἵλεως ᾖ ὁ θεός, ἐγὼ ἀνὴρ ἀγαθὸς γίγνεσθαι πειράσομαι, ἄξιος τῶν πατέρων. ἀλλὰ τί ἐποίεις σὺ ἐν τῇ εἰρήνῃ;”",
      "ὁ δὲ γέρων, “οὐκέτι νεανίας ἦν ἐγώ,” ἔφη, “οὐδὲ τοσαύτῃ ῥώμῃ ἐχρώμην ὥστε ἐν τῷ ναυτικῷ ἐρέσσειν.",
      "μισθοφορῶν οὖν ἐν ὁλκάσι πολλαχόσε τῆς γῆς ἔπλεον.",
      "εἴς τε γὰρ τὴν Σικελίαν ἦλθον, οὗπερ τὸ Αἰτναῖον ὄρος εἶδον ποταμοὺς πυρὸς πρὸς τὸν οὐρανὸν ἐκβάλλον, καὶ εἰς τὴν Σκυθίαν ἔπλευσα, οὗπερ τοῦ χειμῶνος τοσαῦτά ἐστιν τὰ ψύχη ὥστε πήγνυσθαι καὶ τὴν θάλατταν.",
      "νῦν δὲ μάλα γεραιὸς ὢν πλοῦς τινας μικροὺς ποιοῦμαι περὶ τὰς νήσους, καὶ θάνατον εὔκολος προσδέχομαι.”",
