     "lines_en": [
      "And Philip said, “Having suffered so great a disaster, did you not stop the war?”",
      "And the sailor said, “Not in the least; for nothing could break the spirit of the Athenians.",
      "So shortly afterward Cimon, having led the fleet to Cyprus, defeated the Persians again, but he himself died while besieging a certain city.",
      "So we, grieving, sailed home.",
      "And in the following year the people made a treaty with the King.",
      "So these are the things we accomplished, fighting against the barbarians.",
      "So a very great contest lies before you, my boy; for you must become worthy of your fathers.”",
      "And Philip said, “You speak the truth, old man; and if the god is gracious, I will try to become a good man, worthy of my fathers. But what did you do during the peace?”",
      "And the old man said, “I was no longer a young man, nor did I have such strength that I could row in the navy.",
      "So working for pay on merchant-ships, I sailed to many places on earth.",
      "For I went to Sicily, where I saw Mount Etna throwing rivers of fire up toward the sky, and I sailed to Scythia, where in winter the cold is so great that even the sea freezes.",
      "But now, being a very old man, I make some small voyages around the islands, and I await death without complaint.”",
      "And Philip said, “You have seen many things, old man, in your long life, and suffered many things too. For not even Odysseus himself wandered farther than you.”",
      "And the old man, having looked toward the land, stood up and said, “Look, we are already arriving at the harbor. Farewell, then; for I must hurry and help the other sailors.”",
      "Having said this, he went off toward the bow, while they remained, pondering everything he had said.",
      "And when they came within the very deep harbor, they furled the sails, and stowed them swiftly in the black ship, and rowed her with oars into the anchorage.",
      "So when the ship was anchored by the mole, the people disembarked onto the land.",
      "And having disembarked, some hurried home, others walked into the city, looking for a wine-shop."
     ],
