      "ἐγὼ γὰρ ἐνίοτε οὐ δύναμαι ἀροῦν τὸν ἀγρὸν τὸν ἐμόν, ὅτε πολλοὶ λίθοι εἰσὶν οἳ τὸ ἄροτρον ἐμποδίζουσιν, οὐδὲ σὺ δύνασαι μετὰ τοῦ δούλου σπείρειν τὴν γῆν καὶ φυτεύειν τὰς ἀμπέλους εἰ μὴ ἐκφέρομεν τοὺς λίθους ἐκ τοῦ ἀγροῦ·",
