      "οὐδὲν ἄλλο γὰρ ἠπιστάμεθα εἰ μὴ τὴν γεωργίαν καὶ τὴν ναυτικὴν τέχνην· σχολάζοντες γὰρ καὶ μετὰ φίλων τινῶν πλέοντες καὶ θαλαττουργοῦντες τήν τε ναυτικὴν καὶ τὴν ἁλιευτικὴν ἐμάθομεν.”",
