      "ταύτην Ἀσωπὸς ζητῶν ἔμαθεν ὅτι ὁ Ζεὺς ἥρπασε τὴν θυγατέρα.",
      "Ζεὺς δέ, ὀργιζόμενος, Ἀσωπὸν μὲν διώκοντα κεραυνῷ βαλὼν ἤμυνέ τε καὶ ἀπέπεμψεν (διὰ τοῦτο ἔτι καὶ νῦν ἐν τοῖς τοῦ Ἀσωποῦ ὕδασιν ἄνθρακες ἔνεισιν), Αἴγιναν δὲ κομίσας εἰς τὴν τότε Οἰνώνην λεγομένην νῆσον, ἣ νῦν Αἴγινα ἐξ αὐτῆς ὀνομάζεται, παῖδα ἐξ αὐτῆς ἔσχεν, ὀνόματι Αἰακόν.",
