      "ἐνόμισαν γὰρ αὐτὸν μόνον δύνασθαι εὑρεῖν παρὰ τῶν θεῶν τὴν τῶν κακῶν καὶ τῆς συμφορᾶς ἀπαλλαγήν.",
      "ὁ δὲ Αἰακὸς αὐτοῖς ἱκετεύουσιν ἐπείσατο.",
      "ἀνελθὼν οὖν ἐπὶ τὸ Ἑλληνικὸν ὄρος πρῶτον μὲν ἔθυσεν, ἔπειτα δὲ τὰς χεῖρας ἀνέσχεν εἰς οὐρανὸν καί, ἀποκαλέσας τὸν Δία κοινὸν πατέρα τῶν Ἑλλήνων, ηὔξατο οἰκτῖραι τὴν Ἑλλάδα ὑπὸ λιμοῦ διαφθειρομένην.",
      "ἐν ᾧ δὲ ηὔχετο ἐξαίφνης πάντες οἱ παρόντες βροντὴν ἤκουσαν καί, τοὺς ὀφθαλμοὺς ἐπάραντες, τὸν οὐρανὸν νεφελῶν μεστὸν εἶδον·",
      "ὀλίγῳ δὲ ὕστερον ἐκ Διὸς ἐγένετο ὕδωρ πολύ, ὃ ὅλην ἐπλήρωσε τὴν χώραν.",
      "ἡ δὲ γῆ ἐξ ἐκείνου τοῦ χρόνου πολλοὺς καὶ μεγάλους καρποὺς ἤνεγκε τοῖς Ἕλλησιν.",
      "ἰδού· ἐν γὰρ ἐκείνῳ τῷ ὄρει, ὑφ᾿ οὗ ἡ πόλις κεῖται, ἱερόν ἐστιν, ὃ Αἰακὸς τῷ Πανελληνίῳ Διὶ ᾠκοδόμησεν, ὅπου ἐποιήσατο τὴν εὐχήν.",
      "ὁ δὲ Αἰακὸς ἐκ τῆς γυναικός, Ἐνδηΐδος ὀνόματι, δύο εἶχε παῖδας, Πηλέα καὶ Τελαμῶνα.”",
      "“ὅρα οὖν, ὦ παῖ, τίνες εἰσὶν οἱ τῶν Αἰγινητῶν πρόγονοι.",
      "διὰ τί δὲ κεῖσαι ἐπὶ τῷ καταστρώματι καὶ οὐκ ἔρχῃ εἰς τὴν πόλιν; πολλὰ γὰρ καὶ καλὰ ἄξιά ἐστι θεᾶσθαι.",
      "σὺ δέ, ὦ γεωργέ, τί ἐᾷς τὸν παῖδα κεῖσθαι ἐν τῇ νηΐ;",
      "οὐ πολὺ γὰρ ἀπέχει τοῦ λιμένος τὸ θέατρον, μέγιστον ὄν τε καὶ κάλλιστον· πολλὰ δὲ ἱερά ἐστιν, τὸ μὲν Ἀπόλλωνος, τὸ δὲ Ἀρτέμιδος, τὸ δὲ Διονύσου, καὶ ἄλλα καὶ πολλά.",
      "καλλίστη γάρ ἐστιν ἡ νῆσος, καίπερ οὐκέτι ηὔπυργον ἕδος καὶ δίκᾳ ξεναρκέϊ κοινὸν φέγγος, ὥσπερ ᾔσεν ὁ ποιητής.”",
      "ὁ δὲ Δικαιόπολις στενάζων, “κεῖται μὲν ὁ παῖς,” ἔφη, “ἐπεὶ μόλις βαδίζειν δύναται τῆς ἐμῆς χειρὸς ἐχόμενος· τυφλὸς γάρ ἐστιν.",
      "διὰ τοῦτο νῦν πλέομεν πρὸς τὴν Ἐπίδαυρον· βουλόμεθα γὰρ εὔχεσθαι τῷ Ἀσκληπιῷ, εἴ πως ἐθέλει αὐτὸν θεραπεύειν καὶ ἰᾶσθαι.”",
      "ὁ δὲ ναύτης· “συλλυποῦμαι ὑμῖν, καὶ οἰκτίρω τὸν παῖδα· δεῖ δὲ ὑμᾶς οὐδὲν ἧττον, ἐκβάντας ἐκ τῆς νεώς, δεῖπνον ἑλέσθαι.",
      "οὐ γὰρ πολὺν χρόνον ἐνταῦθα μένειν δυνάμεθα· βούλεται γὰρ ὁ ναύκληρος πρὸ τῆς νυκτὸς εἰς τὴν Ἐπίδαυρον ἀφικέσθαι.",
      "ἐγὼ μὲν οὐ δύναμαι ὑμῖν ἡγεῖσθαι—κελεύει γάρ με ἐν τῇ νηῒ μένειν ὁ ναύκληρος—οὐ χαλεπὸν δέ ἐστιν ἐν τῇ πόλει οἰνοπώλιον εὑρεῖν.”",
      "ταῦτ᾿ εἰπών, “χαίρετε οὖν,” ἔφη, “δεῖ γὰρ νῦν με τοῖς ἄλλοις ναύταις συλλαμβάνειν· δεῖ γὰρ ἡμᾶς πολλὰ φορτία, ἃ ἐν τῷ καταστρώματι κεῖται, ἐκ τῆς νεὼς ἐκφέρειν.”"
